/* From Uiverse.io by mobinkakei - Tags: checkbox */
.__UIV_SCOPE__ .toggler {
  width: 72px;
  margin: 40px auto;
}

.__UIV_SCOPE__ .toggler input {
  display: none;
}

.__UIV_SCOPE__ .toggler label {
  display: block;
  position: relative;
  width: 72px;
  height: 36px;
  border: 1px solid #d6d6d6;
  border-radius: 36px;
  background: #e4e8e8;
  cursor: pointer;
}

.__UIV_SCOPE__ .toggler label::after {
  display: block;
  border-radius: 100%;
  background-color: #d7062a;
  content: '';
  animation-name: toggler-size;
  animation-duration: 0.15s;
  animation-timing-function: ease-out;
  animation-direction: forwards;
  animation-iteration-count: 1;
  animation-play-state: running;
}

.__UIV_SCOPE__ .toggler label::after, .__UIV_SCOPE__ .toggler label .toggler-on, .__UIV_SCOPE__ .toggler label .toggler-off {
  position: absolute;
  top: 50%;
  left: 25%;
  width: 26px;
  height: 26px;
  transform: translateY(-50%) translateX(-50%);
  transition: left 0.15s ease-in-out, background-color 0.2s ease-out, width 0.15s ease-in-out, height 0.15s ease-in-out, opacity 0.15s ease-in-out;
}

.__UIV_SCOPE__ .toggler input:checked + label::after, .__UIV_SCOPE__ .toggler input:checked + label .toggler-on, .__UIV_SCOPE__ .toggler input:checked + label .toggler-off {
  left: 75%;
}

.__UIV_SCOPE__ .toggler input:checked + label::after {
  background-color: #50ac5d;
  animation-name: toggler-size2;
}

.__UIV_SCOPE__ .toggler .toggler-on, .__UIV_SCOPE__ .toggler .toggler-off {
  opacity: 1;
  z-index: 2;
}

.__UIV_SCOPE__ .toggler input:checked + label .toggler-off, .__UIV_SCOPE__ .toggler input:not(:checked) + label .toggler-on {
  width: 0;
  height: 0;
  opacity: 0;
}

.__UIV_SCOPE__ .toggler .path {
  fill: none;
  stroke: #fefefe;
  stroke-width: 7px;
  stroke-linecap: round;
  stroke-miterlimit: 10;
}

@keyframes toggler-size {
  0%, 100% {
    width: 26px;
    height: 26px;
  }

  50% {
    width: 20px;
    height: 20px;
  }
}

@keyframes toggler-size2 {
  0%, 100% {
    width: 26px;
    height: 26px;
  }

  50% {
    width: 20px;
    height: 20px;
  }
}
